<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Trusted Health & Wellness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f5fbfa;
      --surface: #ffffff;
      --surface-soft: #eef7f5;
      --text: #183633;
      --muted: #5f7774;
      --primary: #1f8b7a;
      --primary-700: #116c5f;
      --accent: #f2a85b;
      --coral: #f08f7a;
      --border: #d8ebe7;
      --shadow: 0 10px 24px rgba(16, 72, 66, 0.08);
      --radius: 18px;
      --radius-sm: 12px;
      --container: 1180px;
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #f8fdfc 0%, #f5fbfa 44%, #ffffff 100%);
      line-height: 1.5;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container { width: min(var(--container), 92vw); margin: 0 auto; }
    .section { padding: 46px 0; }

    .topbar {
      background: var(--surface);
      border-bottom: 1px solid var(--border);
      position: sticky;
      top: 0;
      z-index: 40;
      backdrop-filter: blur(7px);
    }

    .topbar-inner {
      display: grid;
      grid-template-columns: 210px 1fr auto;
      align-items: center;
      gap: 20px;
      min-height: 74px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      letter-spacing: -0.02em;
      font-size: 1.35rem;
      color: var(--primary-700);
    }

    .logo-mark {
      width: 34px;
      aspect-ratio: 1;
      border-radius: 50%;
      background: radial-gradient(circle at 30% 30%, #7be2ce 0%, #2c9e8b 55%, #1f8b7a 100%);
      display: grid;
      place-items: center;
      color: #fff;
      font-size: 0.95rem;
      font-weight: 700;
      box-shadow: var(--shadow);
    }

    nav ul {
      list-style: none;
      margin: 0;
      padding: 0;
      display: flex;
      justify-content: center;
      gap: 6px;
      flex-wrap: wrap;
    }

    .nav-btn {
      border: 1px solid transparent;
      background: transparent;
      color: var(--text);
      border-radius: 999px;
      padding: 9px 14px;
      font-weight: 600;
      cursor: pointer;
      transition: .2s ease;
      font-size: 0.95rem;
    }

    .nav-btn:hover,
    .nav-btn[aria-expanded="true"] {
      background: #e7f4f1;
      border-color: #cbe6e1;
      color: var(--primary-700);
    }

    .topbar-actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .search {
      border: 1px solid var(--border);
      background: var(--surface-soft);
      border-radius: 999px;
      padding: 8px 12px;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .btn {
      border: 0;
      border-radius: 999px;
      font-weight: 700;
      cursor: pointer;
      padding: 10px 17px;
      transition: .2s ease;
    }

    .btn-primary {
      background: var(--primary);
      color: #fff;
      box-shadow: 0 8px 16px rgba(31, 139, 122, 0.22);
    }

    .btn-primary:hover { background: var(--primary-700); }

    .mega-wrap {
      position: relative;
      background: var(--surface);
      border-bottom: 1px solid var(--border);
    }

    .mega-menu {
      display: none;
      position: absolute;
      inset: 0 auto auto 50%;
      transform: translateX(-50%);
      width: min(1000px, 96vw);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 0 0 18px 18px;
      box-shadow: var(--shadow);
      padding: 22px;
      z-index: 35;
    }

    .mega-menu.active { display: block; }

    .mega-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 20px;
    }

    .mega-col h4 { margin: 0 0 9px; color: var(--primary-700); }
    .mega-col a {
      display: block;
      color: var(--muted);
      padding: 5px 0;
      font-size: 0.95rem;
    }

    .mega-col a:hover { color: var(--primary-700); }

    .ticker {
      margin-top: 10px;
      background: #e4f4f1;
      border-block: 1px solid #cbe6e1;
      overflow: hidden;
      white-space: nowrap;
      position: relative;
    }

    .ticker-track {
      display: inline-flex;
      gap: 26px;
      padding: 11px 0;
      animation: ticker 26s linear infinite;
      min-width: 100%;
    }

    .ticker-item {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: #225f57;
      font-weight: 600;
    }

    .dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--accent);
    }

    @keyframes ticker {
      from { transform: translateX(0); }
      to { transform: translateX(-50%); }
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.2fr .8fr;
      gap: 24px;
      align-items: stretch;
      margin-top: 20px;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }

    .featured {
      overflow: hidden;
      display: grid;
      grid-template-rows: 250px auto;
    }

    .featured img { width: 100%; height: 100%; object-fit: cover; }
    .featured-body { padding: 22px; }

    .tag {
      display: inline-block;
      font-size: .78rem;
      font-weight: 700;
      letter-spacing: .01em;
      color: #fff;
      border-radius: 999px;
      background: var(--primary);
      padding: 5px 10px;
      margin-bottom: 10px;
    }

    h1, h2, h3 { line-height: 1.2; margin: 0 0 10px; letter-spacing: -0.02em; }
    h1 { font-size: clamp(1.6rem, 2.8vw, 2.25rem); }
    h2 { font-size: clamp(1.3rem, 2.2vw, 1.85rem); }

    .muted { color: var(--muted); }

    .trending { padding: 20px; }
    .trend-list { list-style: none; margin: 16px 0 0; padding: 0; display: grid; gap: 14px; }

    .trend-item {
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 13px;
      background: #fbfefd;
    }

    .trend-item small { color: var(--primary-700); font-weight: 700; display: block; margin-bottom: 5px; }
    .trend-item p { margin: 0; font-weight: 600; }

    .topics-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 14px;
      gap: 12px;
      flex-wrap: wrap;
    }

    .carousel-controls { display: flex; gap: 8px; }

    .arrow-btn {
      border: 1px solid var(--border);
      background: var(--surface);
      width: 36px;
      height: 36px;
      border-radius: 50%;
      cursor: pointer;
      font-size: 1.1rem;
      color: var(--primary-700);
    }

    .topics-track {
      display: flex;
      gap: 14px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding-bottom: 6px;
      scrollbar-width: thin;
    }

    .topic-card {
      min-width: 170px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 14px;
      text-align: center;
      box-shadow: var(--shadow);
    }

    .topic-avatar {
      width: 102px;
      height: 102px;
      margin: 0 auto 11px;
      border-radius: 50%;
      object-fit: cover;
      border: 4px solid #dff2ee;
    }

    .tools-grid,
    .reads-grid,
    .pillar-grid {
      display: grid;
      gap: 16px;
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .tool-card,
    .read-card,
    .pillar {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 18px;
      box-shadow: var(--shadow);
    }

    .tool-card h3,
    .read-card h3 { font-size: 1.04rem; }

    .tabs {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding-bottom: 4px;
      margin-bottom: 16px;
    }

    .tab {
      border: 1px solid #cde7e3;
      background: #f2fbf9;
      color: #275c56;
      border-radius: 999px;
      padding: 8px 13px;
      font-weight: 600;
      cursor: pointer;
      white-space: nowrap;
    }

    .tab.active {
      background: var(--primary);
      color: #fff;
      border-color: var(--primary);
    }

    .newsletter {
      background: linear-gradient(130deg, #1f8b7a 0%, #276f87 100%);
      color: #fff;
      border-radius: 24px;
      padding: 30px;
      display: grid;
      grid-template-columns: 1.2fr .8fr;
      gap: 16px;
      align-items: center;
    }

    .newsletter form {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .newsletter input {
      min-width: 260px;
      border: 0;
      border-radius: 999px;
      padding: 12px 14px;
      font: inherit;
    }

    .newsletter .btn-primary {
      background: var(--accent);
      color: #2d2925;
      box-shadow: none;
    }

    .newsletter .btn-primary:hover { background: #f4ba7e; }

    .pillar {
      position: relative;
      padding-top: 20px;
    }

    .pillar::before {
      content: "";
      position: absolute;
      top: 0;
      left: 18px;
      width: 58px;
      height: 4px;
      border-radius: 10px;
      background: var(--coral);
    }

    footer {
      margin-top: 26px;
      border-top: 1px solid var(--border);
      padding: 22px 0 34px;
      color: var(--muted);
      font-size: .92rem;
      text-align: center;
    }

    @media (max-width: 1000px) {
      .topbar-inner { grid-template-columns: 1fr; gap: 10px; padding: 12px 0; }
      nav ul { justify-content: flex-start; }
      .hero-grid,
      .newsletter,
      .tools-grid,
      .reads-grid,
      .pillar-grid,
      .mega-grid { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 720px) {
      .hero-grid,
      .tools-grid,
      .reads-grid,
      .pillar-grid,
      .newsletter,
      .mega-grid { grid-template-columns: 1fr; }
      .featured { grid-template-rows: 210px auto; }
      .newsletter form { justify-content: flex-start; }
      .newsletter input { min-width: 100%; }
      .ticker-item { font-size: .9rem; }
    }
  </style>
</head>
<body>
