        { title: 'Type 2 Diabetes', img: 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=500&q=80' },
        { title: 'Weight Management', img: 'https://images.unsplash.com/photo-1484981138541-3d074aa97716?auto=format&fit=crop&w=500&q=80' },
        { title: 'Sleep Health', img: 'https://images.unsplash.com/photo-1455642305367-68834a19cb81?auto=format&fit=crop&w=500&q=80' },
        { title: 'Immune Support', img: 'https://images.unsplash.com/photo-1478144592103-25e218a04891?auto=format&fit=crop&w=500&q=80' }
