    };

    const tickerTrack = document.getElementById('ticker-track');
    const tickerItems = [...content.credibilityStats, ...content.credibilityStats];
    tickerTrack.innerHTML = tickerItems.map(item => `<span class="ticker-item"><span class="dot"></span>${item}</span>`).join('');

    const trendingList = document.getElementById('trending-list');
    trendingList.innerHTML = content.trendingArticles.map(article => `
      <li class="trend-item">
        <small>${article.category}</small>
        <p>${article.title}</p>
      </li>
    `).join('');

    const topicsTrack = document.getElementById('topics-track');
    topicsTrack.innerHTML = content.healthTopics.map(topic => `
      <article class="topic-card">
        <img class="topic-avatar" src="${topic.img}" alt="${topic.title}" />
        <h3>${topic.title}</h3>
      </article>
    `).join('');

    document.getElementById('topics-left').addEventListener('click', () => {
      topicsTrack.scrollBy({ left: -240, behavior: 'smooth' });
    });

    document.getElementById('topics-right').addEventListener('click', () => {
      topicsTrack.scrollBy({ left: 240, behavior: 'smooth' });
    });

    const toolsGrid = document.getElementById('tools-grid');
    toolsGrid.innerHTML = content.tools.map(tool => `
      <article class="tool-card">
        <h3>${tool.name}</h3>
        <p class="muted">${tool.desc}</p>
      </article>
    `).join('');

    const tabsEl = document.getElementById('reads-tabs');
    const readsGrid = document.getElementById('reads-grid');
    const tabNames = Object.keys(content.recommendedReads);

    function renderReads(tab) {
      readsGrid.innerHTML = content.recommendedReads[tab].map(title => `
