    };

    const tickerTrack = document.getElementById('ticker-track');
    const tickerItems = [...content.credibilityStats, ...content.credibilityStats];
    tickerTrack.innerHTML = tickerItems.map(item => `<span class="ticker-item"><span class="dot"></span>${item}</span>`).join('');

    const trendingList = document.getElementById('trending-list');
    trendingList.innerHTML = content.trendingArticles.map(article => `
      <li class="trend-item">
        <small>${article.category}</small>
        <p>${article.title}</p>
      </li>
    `).join('');

    const topicsTrack = document.getElementById('topics-track');
    topicsTrack.innerHTML = content.healthTopics.map(topic => `
      <article class="topic-card">
        <img class="topic-avatar" src="${topic.img}" alt="${topic.title}" />
        <h3>${topic.title}</h3>
      </article>
    `).join('');

    document.getElementById('topics-left').addEventListener('click', () => {
      topicsTrack.scrollBy({ left: -240, behavior: 'smooth' });
    });

    document.getElementById('topics-right').addEventListener('click', () => {
      topicsTrack.scrollBy({ left: 240, behavior: 'smooth' });
    });

    const toolsGrid = document.getElementById('tools-grid');
    toolsGrid.innerHTML = content.tools.map(tool => `
      <article class="tool-card">
        <h3>${tool.name}</h3>
        <p class="muted">${tool.desc}</p>
      </article>
    `).join('');

    const tabsEl = document.getElementById('reads-tabs');
    const readsGrid = document.getElementById('reads-grid');
    const tabNames = Object.keys(content.recommendedReads);

    function renderReads(tab) {
      readsGrid.innerHTML = content.recommendedReads[tab].map(title => `
        <article class="read-card">
          <span class="tag" style="background:#2f9c8a">${tab}</span>
          <h3>${title}</h3>
          <p class="muted">Medically reviewed insights with practical takeaways.</p>
        </article>
      `).join('');
    }

    tabsEl.innerHTML = tabNames.map((tab, index) => `
      <button class="tab ${index === 0 ? 'active' : ''}" role="tab" aria-selected="${index === 0}" data-tab="${tab}">${tab}</button>
    `).join('');

    tabsEl.addEventListener('click', (event) => {
      const tab = event.target.closest('[data-tab]');
      if (!tab) return;
      [...tabsEl.children].forEach(btn => {
        btn.classList.remove('active');
        btn.setAttribute('aria-selected', 'false');
      });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');
      renderReads(tab.dataset.tab);
    });

    renderReads(tabNames[0]);

    const pillarGrid = document.getElementById('pillar-grid');
    pillarGrid.innerHTML = content.trustPillars.map(p => `
      <article class="pillar">
        <h3>${p.title}</h3>
        <p class="muted">${p.text}</p>
      </article>
    `).join('');

    const megaMenu = document.getElementById('mega-menu');
    const navButtons = document.querySelectorAll('.nav-btn');

    function closeMenu() {
      megaMenu.classList.remove('active');
      navButtons.forEach(btn => btn.setAttribute('aria-expanded', 'false'));
    }

    function openMenu(menuKey, triggerBtn) {
      const menuData = content.megaMenu[menuKey];
      if (!menuData) return;
      const columns = Object.entries(menuData.columns).map(([title, links]) => `
        <div class="mega-col">
          <h4>${title}</h4>
          ${links.map(link => `<a href="#">${link}</a>`).join('')}
        </div>
      `).join('');

      megaMenu.innerHTML = `<div class="mega-grid">${columns}</div>`;
      megaMenu.classList.add('active');
      navButtons.forEach(btn => btn.setAttribute('aria-expanded', String(btn === triggerBtn)));
    }

    navButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        const isOpen = btn.getAttribute('aria-expanded') === 'true';
        if (isOpen) {
          closeMenu();
        } else {
          openMenu(btn.dataset.menu, btn);
        }
      });
    });

    document.addEventListener('click', (event) => {
      const insideNav = event.target.closest('nav') || event.target.closest('#mega-menu');
      if (!insideNav) closeMenu();
    });

    const newsletterForm = document.getElementById('newsletter-form');
    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const emailInput = document.getElementById('newsletter-email');
      if (!emailInput.value.trim()) return;
      alert(`Thanks for joining WellSource, ${emailInput.value.trim()}!`);
      emailInput.value = '';
    });
  </script>
